<form class="trial-form" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" method="post"><?php wp_nonce_field( 'forgetfit_trial', 'forgetfit_trial_nonce' ); ?><input type="hidden" name="action" value="forgetfit_trial"><?php if ( isset( $_GET['trial'] ) ) : ?><div class="form-status"><?php echo 'success' === sanitize_key( wp_unslash( $_GET['trial'] ) ) ? esc_html__( 'Thank you. We will be in touch shortly.', 'forgetfit' ) : esc_html__( 'Please check your details and try again.', 'forgetfit' ); ?></div><?php endif; ?><div class="form-field"><label for="trial-name"><?php esc_html_e( 'Name', 'forgetfit' ); ?></label><input id="trial-name" name="trial_name" type="text" autocomplete="name" required></div><div class="form-field"><label for="trial-email"><?php esc_html_e( 'Email', 'forgetfit' ); ?></label><input id="trial-email" name="trial_email" type="email" autocomplete="email" required></div><div class="form-field"><label for="trial-phone"><?php esc_html_e( 'Phone', 'forgetfit' ); ?></label><input id="trial-phone" name="trial_phone" type="tel" autocomplete="tel"></div><div class="form-field"><label for="trial-program"><?php esc_html_e( 'What brings you in?', 'forgetfit' ); ?></label><select id="trial-program" name="trial_program"><option><?php esc_html_e( 'I want to try the gym', 'forgetfit' ); ?></option><option><?php esc_html_e( 'Build strength', 'forgetfit' ); ?></option><option><?php esc_html_e( 'Join group classes', 'forgetfit' ); ?></option><option><?php esc_html_e( 'Personal coaching', 'forgetfit' ); ?></option></select></div><div class="form-field form-field--full"><button class="btn" type="submit"><?php echo esc_html( get_theme_mod( 'forgetfit_cta_label', __( 'Get a free pass', 'forgetfit' ) ) ); ?></button></div><p class="form-note"><?php esc_html_e( 'No pressure. Tour the gym, meet the team, and try a workout.', 'forgetfit' ); ?></p></form>

